mapper.select:
SELECT po.po_id, po.po_number, v.vendor_code, v.name AS vendor_name, po.status, po.order_date, po.expected_date, COUNT(pol.po_line_id) AS line_count, COALESCE(SUM(pol.quantity_ordered), 0) AS total_ordered, COALESCE(SUM(pol.quantity_received), 0) AS total_received FROM purchase_order po JOIN vendor v ON v.vendor_id = po.vendor_id LEFT JOIN purchase_order_line pol ON pol.po_id = po.po_id
AND po.status IN
#{s}
AND po.vendor_id = #{criteria.vendorId}
AND LOWER(po.po_number) LIKE LOWER('%' || #{criteria.poNumberContains} || '%')
GROUP BY po.po_id, po.po_number, v.vendor_code, v.name, po.status, po.order_date, po.expected_date ORDER BY ${criteria.sort.columnName}

mapper.update:
UPDATE purchase_order_line
SET quantity_received = quantity_received + #{delta}
WHERE po_line_id = #{poLineId}

UPDATE purchase_order
SET status     = #{status},
    updated_at = now(),
    updated_by = #{updatedBy}
WHERE po_id = #{poId}
